  public static Future<List<PostPictureInQuery>> upload(
      String s3Dir, List<BufferedImage> images, List<String> names, boolean multiResolution) {
    Vertx vertx = Vertx.currentContext().owner();
    AtomicInteger index = new AtomicInteger(0);
    List<String> picturesLocalPath = new ArrayList<>();
    List<PostPictureInQuery> picturesInfo = new ArrayList<>();

    List<Future<String>> uploadFutures =
        images.stream()
            .map(
                image -> {
                  String fileName = names.get(index.getAndIncrement());
                  String fileType = fileName.substring(fileName.lastIndexOf(".") + 1);
                  return processImage(
                      s3Dir, picturesInfo, image, fileType, fileName, multiResolution);
                })
            .flatMap(List::stream)
            .map(
                pictureTmpName -> {
                  String pictureTmpPath = String.format("%s/%s", TMP_FILE_DIR, pictureTmpName);
                  picturesLocalPath.add(pictureTmpPath);
                  return GoogleStorageUtils.uploadFile(
                      S3_BUCKET, pictureTmpName, s3Dir, pictureTmpPath, vertx);
                })
            .collect(Collectors.toList());
    return Future.all(uploadFutures)
        .compose(
            res -> {
              picturesLocalPath.forEach(FileUtils::deleteFileSilently);
              return Future.succeededFuture(picturesInfo);
            })
        .onFailure(
            e -> {
              log.error("upload pictures fail, msg: {}", e.getMessage(), e);
              picturesLocalPath.forEach(FileUtils::deleteFileSilently);
            });
  }

