  /**
   * 渐进式图片压缩，通过多步骤缩放获得更好的质量
   */
  public static BufferedImage compressImageProgressively(BufferedImage originalImage, int targetWidth, int targetHeight) {
    int currentWidth = originalImage.getWidth();
    int currentHeight = originalImage.getHeight();

    BufferedImage currentImage = originalImage;

    // 如果需要大幅缩小，使用渐进式缩放
    while (currentWidth > targetWidth * 2 || currentHeight > targetHeight * 2) {
      currentWidth = Math.max(currentWidth / 2, targetWidth);
      currentHeight = Math.max(currentHeight / 2, targetHeight);

      BufferedImage tempImage = createHighQualityScaledImage(currentImage, currentWidth, currentHeight);

      // 清理中间图片资源（除了原始图片）
      if (currentImage != originalImage) {
        cleanResource(currentImage);
      }

      currentImage = tempImage;
    }

    // 最后一步缩放到目标尺寸
    if (currentWidth != targetWidth || currentHeight != targetHeight) {
      BufferedImage finalImage = createHighQualityScaledImage(currentImage, targetWidth, targetHeight);

      // 清理最后的中间图片
      if (currentImage != originalImage) {
        cleanResource(currentImage);
      }

      return finalImage;
    }

    return currentImage;
  }

  /**
   * 创建高质量缩放图片
   */
  private static BufferedImage createHighQualityScaledImage(BufferedImage sourceImage, int targetWidth, int targetHeight) {
    // 使用TYPE_INT_ARGB来支持透明度（Alpha通道）
    BufferedImage scaledImage = new BufferedImage(targetWidth, targetHeight, BufferedImage.TYPE_INT_ARGB);

    Graphics2D graphics = scaledImage.createGraphics();

    // 设置最高质量的渲染提示
    graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
    graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
    graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
    graphics.setRenderingHint(RenderingHints.KEY_COLOR_RENDERING, RenderingHints.VALUE_COLOR_RENDER_QUALITY);
    graphics.setRenderingHint(RenderingHints.KEY_DITHERING, RenderingHints.VALUE_DITHER_ENABLE);
    graphics.setRenderingHint(RenderingHints.KEY_ALPHA_INTERPOLATION, RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
    graphics.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

    // 绘制缩放后的图片
    graphics.drawImage(sourceImage, 0, 0, targetWidth, targetHeight, null);
    graphics.dispose();

    return scaledImage;
  }

