  /**
   * 纯函数：图片超过 thresholdBytes 时只做一次 Scalr.resize（最长边 800）+ JPEG 编码。
   * 不修改入参；不保证压缩后大小，压缩失败才抛异常，调用方不得回退到原图上传。
   */
  public static byte[] compressImageIfOversize(byte[] imageData, int thresholdBytes) {
    if (imageData == null || imageData.length <= thresholdBytes) {
      return imageData;
    }
    BufferedImage original;
    try {
      original = readImageFromByteArray(imageData);
    } catch (RuntimeException e) {
      throw new IllegalArgumentException("Failed to read image data", e);
    }
    if (original == null || original.getWidth() <= 0 || original.getHeight() <= 0) {
      throw new IllegalArgumentException("Failed to read image data");
    }

    BufferedImage resized = null;
    try {
      int target = Math.min(800, Math.max(original.getWidth(), original.getHeight()));
      resized = Scalr.resize(original, Scalr.Method.QUALITY, target);
      return toJpegBytes(resized);
    } finally {
      cleanResource(original);
      if (resized != null && resized != original) {
        cleanResource(resized);
      }
    }
  }

  private static byte[] toJpegBytes(BufferedImage image) {
    BufferedImage rgb =
        new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_RGB);
    Graphics2D graphics = rgb.createGraphics();
    try {
      graphics.setColor(Color.WHITE);
      graphics.fillRect(0, 0, rgb.getWidth(), rgb.getHeight());
      graphics.drawImage(image, 0, 0, null);
    } finally {
      graphics.dispose();
    }
    try {
      ByteArrayOutputStream out = new ByteArrayOutputStream();
      if (!ImageIO.write(rgb, "jpg", out)) {
        throw new IllegalStateException("No JPEG writer available");
      }
      return out.toByteArray();
    } catch (IOException e) {
      throw new IllegalStateException("Failed to encode JPEG", e);
    } finally {
      cleanResource(rgb);
    }
  }

