  public static List<String> processImage(
      String s3Dir,
      List<PostPictureInQuery> postPictures,
      BufferedImage image,
      String fileType,
      String fileName,
      boolean multiResolution) {
    if (fileName.isEmpty()) {
      return generateNormalPicWithSpecifiedName(s3Dir, postPictures, image, fileType, fileName);
    }
    if (!multiResolution) {
      return generatePictures(s3Dir, postPictures, image, fileType, false, false);
    } else {
      if (image.getWidth() > MID_PIC_TARGET_LEN && image.getHeight() > MID_PIC_TARGET_LEN) {
        // 需要生成中等尺寸和小尺寸图片
        return generatePictures(s3Dir, postPictures, image, fileType, true, true);
      } else if (image.getWidth() > MINI_PIC_TARGET_LEN
          && image.getHeight() > MINI_PIC_TARGET_LEN) {
        // 需要生成小尺寸图片
        return generatePictures(s3Dir, postPictures, image, fileType, false, true);
      } else {
        // 不需要生成其他尺寸图片
        return generatePictures(s3Dir, postPictures, image, fileType, false, false);
      }
    }
