          webClient,
          userId,
          null,
          req.getAvatar().getFile().toByteArray(),
          req.getAvatar().getName()); // 异步更新颜值分
      updateUserPhotoStyle(
          webClient,
          userId,
          null,
          req.getAvatar().getFile().toByteArray(),
          req.getAvatar().getName()); // 异步更新图片描述
      // 响应
      end(
          ctx,
          AdminCreateDigitalHumanResponse.newBuilder()
              .setCode(UserServiceCommonCode.Success)
              .setUserInfo(adminUserInfo));
    } catch (Throwable t) {
      endException(ctx, t);
    }
  }

  public static PictureInQuery uploadAvatar(UploadPicture avatar) {
    PictureInQuery.Builder picture = PictureInQuery.newBuilder();
    try {
      if (avatar.getName().isBlank() || avatar.getFile().isEmpty()) {
        return picture.setState(PictureState.PICTURE_EMPTY).build();
      }
      BufferedImage image = PictureHelper.readImageFromByteArray(avatar.getFile().toByteArray());
      if (image == null) {
        return picture.setState(PictureState.PICTURE_EMPTY).build();
      }
      return await(
          UploadImageUtils.upload(
                  USER_CREATE_CLOUD_STORAGE_DIR, List.of(image), List.of(avatar.getName()), false)
              .compose(
                  images ->
                      Future.succeededFuture(
                          UploadAvatarUtil.fromPostPictureInQuery(images.getFirst()))));
    } catch (Exception e) {
      log.error("uploadAvatar error {}", e.getMessage(), e);
      return picture.setState(PictureState.PICTURE_EMPTY).build();
    }
  }
